using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageDownlevelTests
{
    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedFormattersCarryAttributeOnDownlevelTargets(string symbol)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3, preprocessorSymbols: new[] { symbol });
        string source = """
            using MessagePack;

            namespace Test
            {
                [MessagePackObject]
                public class MyObject
                {
                    [Key(0)]
                    public int Value { get; set; }
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        SyntaxTree inputTree = CSharpSyntaxTree.ParseText(source, parseOptions);
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> refs = new List<MetadataReference>(frameworkRefs);
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { inputTree },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);

        List<INamedTypeSymbol> formatterTypes = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in output.SyntaxTrees)
        {
            if (ReferenceEquals(tree, inputTree))
            {
                continue;
            }

            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax decl in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(decl) is INamedTypeSymbol sym && sym.Name.EndsWith("Formatter", StringComparison.Ordinal))
                {
                    formatterTypes.Add(sym);
                }
            }
        }

        formatterTypes.Should().NotBeEmpty("the generator should emit a formatter for MyObject");
        foreach (INamedTypeSymbol type in formatterTypes)
        {
            type.GetAttributes().Should().Contain(
                a => a.AttributeClass != null && a.AttributeClass.Name == "ExcludeFromCodeCoverageAttribute",
                "ExcludeFromCodeCoverageAttribute exists on netstandard2.0 and .NET Framework, so generated type {0} should carry it when {1} is defined",
                type.Name,
                symbol);
        }
    }
}
